DO $fpcheck$
BEGIN
  IF (SELECT md5(coalesce(string_agg(x, E'\n' ORDER BY x COLLATE "C"), '')) FROM (SELECT c.relname::text || '|' || c.relkind::text || '|' || pg_get_userbyid(c.relowner)::text || '|' || coalesce(c.relacl::text, '-') || '|' || coalesce((SELECT string_agg(a.attname::text || ':' || format_type(a.atttypid, a.atttypmod) || ':' || coalesce(a.attacl::text, '-'), ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped), '') AS x FROM pg_class c WHERE c.relnamespace = to_regnamespace('private') AND c.relkind = 'r' AND c.relname = ANY (ARRAY['incident_auth_counts_20261106','incident_session_ids_20261106','incident_refresh_ids_20261106','qr_token_backup_20261106']::name[])) z) IS DISTINCT FROM current_setting('kil.pack12a.private_fp', true) THEN
    RAISE EXCEPTION '12A ROLLBACK-01-UNSAFE: POST-CHECK FAILED (transaction rolls back): the pre-existing private.* tables (owner / ACL / column list) differ from their state at the start of this pack';
  END IF;
  IF current_setting('kil.pack12a.private_nspacl', true) IS DISTINCT FROM 'ABSENT' AND coalesce((SELECT coalesce(n.nspacl::text, '(null)') FROM pg_namespace n WHERE n.oid = to_regnamespace('private')), 'ABSENT') IS DISTINCT FROM current_setting('kil.pack12a.private_nspacl', true) THEN
    RAISE EXCEPTION '12A ROLLBACK-01-UNSAFE: POST-CHECK FAILED (transaction rolls back): the ACL of the pre-existing schema private changed';
  END IF;
END
$fpcheck$;

