    (SELECT 'known incident table(s) with unexpected owner / ACL / column ACL: ' || string_agg(c.relname::text, ', ' ORDER BY c.relname::text) FROM pg_class c WHERE c.relnamespace = s.oid AND c.relkind = 'r' AND c.relname = ANY (ARRAY['incident_auth_counts_20261106','incident_session_ids_20261106','incident_refresh_ids_20261106','qr_token_backup_20261106']::name[]) AND (c.relowner <> to_regrole('postgres') OR coalesce(c.relacl::text, '{postgres=arwdDxtm/postgres}') <> '{postgres=arwdDxtm/postgres}' OR EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attacl IS NOT NULL)))), '') FROM pg_namespace s WHERE s.oid = to_regnamespace('private')), 'ok'), 'ABSENT') AS actual
  UNION ALL SELECT 'private.client_access' AS name, coalesce(coalesce(nullif(concat_ws(' ; ',
    (SELECT 'schema privilege ' || string_agg(cr.r || ':' || p, ',') FROM (SELECT rolname::text AS r FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')) cr, unnest(ARRAY['USAGE','CREATE']) p WHERE has_schema_privilege(cr.r, to_regnamespace('private')::oid, p)),
    (SELECT 'schema ACL names PUBLIC' FROM pg_namespace n, aclexplode(n.nspacl) x WHERE n.oid = to_regnamespace('private') AND x.grantee = 0 LIMIT 1),
    (SELECT 'relation privilege ' || string_agg(DISTINCT c.relname::text || '/' || cr.r, ',') FROM pg_class c, (SELECT rolname::text AS r FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')) cr WHERE c.relnamespace = to_regnamespace('private') AND c.relkind IN ('r','v','m','S','p','f') AND has_table_privilege(cr.r, c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')),
    (SELECT 'relation ACL names PUBLIC: ' || string_agg(DISTINCT c.relname::text, ',') FROM pg_class c, aclexplode(c.relacl) x WHERE c.relnamespace = to_regnamespace('private') AND x.grantee = 0),
    (SELECT 'default ACL entries in private granting to PUBLIC / client roles: ' || count(*)::text FROM pg_default_acl d, aclexplode(d.defaclacl) x WHERE d.defaclnamespace = to_regnamespace('private') AND (x.grantee = 0 OR x.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role'))) HAVING count(*) > 0)), ''), 'none'), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.relkind_rls' AS name, coalesce((SELECT c.relkind::text||'/'||c.relrowsecurity::text||'/'||c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.columns_md5' AS name, coalesce((SELECT md5(string_agg(a.attname::text||':'||format_type(a.atttypid,a.atttypmod), ',' ORDER BY a.attname::text COLLATE "C")) FROM pg_attribute a WHERE a.attrelid = 'public.event_orders'::regclass AND a.attnum > 0 AND NOT a.attisdropped), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.acl_sorted' AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.policies_md5' AS name, coalesce((SELECT md5(string_agg(x, ',' ORDER BY x COLLATE "C")) FROM (SELECT p.policyname::text||'|'||p.cmd||'|'||(SELECT string_agg(r::text, ',' ORDER BY r::text COLLATE "C") FROM unnest(p.roles) r)||'|'||p.permissive AS x FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'event_orders') s), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.constraints' AS name, coalesce((SELECT string_agg(x, ',' ORDER BY x COLLATE "C") FROM (SELECT c.contype::text||':'||coalesce((SELECT relname::text FROM pg_class WHERE oid = c.confrelid),'-')||':'||coalesce(nullif(c.confdeltype::text,' '),'-')||':'||(SELECT string_agg(a.attname::text, '+' ORDER BY a.attname::text COLLATE "C") FROM pg_attribute a WHERE a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)) AS x FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype IN ('p','f','u','x')) s), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.status_check' AS name, coalesce((SELECT count(*)::text FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype = 'c' AND pg_get_constraintdef(c.oid) ~ 'pending' AND pg_get_constraintdef(c.oid) ~ 'paid' AND pg_get_constraintdef(c.oid) ~ 'checked_in' AND pg_get_constraintdef(c.oid) ~ 'refunded' AND pg_get_constraintdef(c.oid) ~ 'cancelled' AND (SELECT count(*) FROM regexp_matches(pg_get_constraintdef(c.oid), '''[^'']*''', 'g')) = 5), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.check_count' AS name, coalesce((SELECT count(*)::text FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype = 'c'), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.user_triggers' AS name, coalesce((SELECT count(*)::text FROM pg_trigger t WHERE t.tgrelid = 'public.event_orders'::regclass AND NOT t.tgisinternal), 'ABSENT') AS actual
  UNION ALL SELECT 'deps.columns_present' AS name, coalesce((SELECT count(*)::text FROM (VALUES ('events','id'),('events','slug'),('events','title'),('events','owner_handle'),('app_users','id'),('app_users','handle'),('ticket_tiers','id'),('ticket_tiers','name')) v(t,c) WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.'||v.t) AND a.attname = v.c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'deps.auth_uid' AS name, coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.oid = to_regprocedure('auth.uid()')), 'ABSENT') AS actual
), e(name, expected) AS (VALUES
  ('scan.overloads', '1'),
